    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xB1A8394D1F7AC797ULL + 0x821CA7A705BA752EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xB05D776640FC6F49ULL + 0xF958955839EAE680ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xEB3D7D285853F441ULL + 0xC3D62CE83415F16EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xD6519AB837E2463BULL + 0x90F2E70E0620C9D5ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordE = TwistMix64::DiffuseC(pNonce * 0x89E55A72DC861D63ULL + 0xAD2AC8936F02B0FCULL);
    [[maybe_unused]] const std::uint64_t aNonceWordF = TwistMix64::DiffuseC(pNonce * 0x8C14BDB0EC512845ULL + 0xEF8751C866DBF19CULL);
    [[maybe_unused]] const std::uint64_t aNonceWordG = TwistMix64::DiffuseA(pNonce * 0xCAF69FCD41215A9BULL + 0x90FB79D5C3A70C1DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xD341AF7141F137B3ULL + 0xAFA8908145A21DCEULL);
    [[maybe_unused]] const std::uint64_t aNonceWordI = TwistMix64::DiffuseA(pNonce * 0x93A6666FAFACDC45ULL + 0xEFD1567B35BDFBCFULL);
    [[maybe_unused]] const std::uint64_t aNonceWordJ = TwistMix64::DiffuseA(pNonce * 0xADC10E4579E78341ULL + 0x9051BDDE1F53CC48ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordK = TwistMix64::DiffuseA(pNonce * 0xABE5A15A2E41001DULL + 0x9CB69078168B2C5DULL);
    [[maybe_unused]] const std::uint64_t aNonceWordL = TwistMix64::DiffuseA(pNonce * 0xFB9665C7D2415829ULL + 0x959F691522867D60ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xE4B53A579FFC1CADULL + 0xB9D771328F46D032ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordN = TwistMix64::DiffuseA(pNonce * 0xD2F61E37777EDD3FULL + 0x8E3D17C219B4CBF3ULL);
    [[maybe_unused]] const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xCB7B514DEFE8B183ULL + 0xF628DF1B86773231ULL);
