            aCross = (RotL64(aWoodLaneC[((S_BLOCK1 - aIndex + 3041U)) & S_BLOCK1], 19U) ^ RotL64(aWoodLaneD[((S_BLOCK1 - aIndex + 903U)) & S_BLOCK1], 10U));
            aCross ^= RotL64(pCrossLaneD[((S_BLOCK1 - aIndex + 1986U)) & S_BLOCK1], 37U);
