            //
            aOrbiterH = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 51U)) + 0x668F1E348315F5BFULL;
            aOrbiterA = (((aWandererE + RotL64(aCross, 5U)) + RotL64(aCarry, 27U)) + 0xE2695E4D62A9C8EFULL) + aTwistOrbiterAssignSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aScatter, 19U)) + 0x9016F50459808CBBULL;
            aOrbiterB = ((aWandererI + RotL64(aPrevious, 60U)) + RotL64(aCarry, 39U)) + 0xE50173CBE684B5C8ULL;
            aOrbiterK = (aWandererK + RotL64(aScatter, 11U)) + 0x1828D053219A69F0ULL;
            aOrbiterD = (aWandererD + RotL64(aPrevious, 43U)) + 0xFBE5BD684F87838CULL;
            aOrbiterE = ((aWandererA + RotL64(aCross, 37U)) + 0x34FD56589F4B2482ULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xC519BF23DEF7E07EULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x9F285DA52DCF932CULL;
            aOrbiterF = RotL64((aOrbiterF * 0x53130E2B235C78FDULL), 29U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x54D98C1BCBA75E12ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x8B7B5015A96C9974ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD2AFAE5F53EF725FULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0x685E5DCDCBD5EF3BULL) + aTwistOrbiterUpdateSaltB[((aIndex + 14U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x8BC286CB7CCC19F0ULL;
