            aCross ^= (RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 15592U)) & S_BLOCK1], 3U) ^ RotL64(aMagmaLaneD[((aIndex + 16318U)) & S_BLOCK1], 23U));
