            aWandererC = aWandererC ^ ((RotL64(aScatter, 51U) + aOrbiterI) + RotL64(aOrbiterD, 37U));
            aWandererI = aWandererI + (((RotL64(aIngress, 47U) + aOrbiterC) + RotL64(aOrbiterD, 11U)) + RotL64(aCarry, 51U));
