            aOrbiterG = (aWandererG + RotL64(aScatter, 35U)) + 0x2448789A58918560ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x7C4B3A1ABDF01218ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0x77706E838AE5A3F9ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 23U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x78D06B6ABBB037C1ULL), 29U);
