            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xE971BF47D9023478ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xB948D90CF68BD593ULL), 3U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterG) + 0x3A1B2965EAA1694AULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 4U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x1D61DD991A0A63F8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xF35EF4E975463DE5ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0x06F3CF877861864AULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xCCF54584EAEB928EULL;
