            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 22028U)) & S_BLOCK1], 60U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 18969U)) & S_BLOCK1], 43U));
