            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = (aWandererF + RotL64(aScatter, 29U)) + 0x90DEF9F306502063ULL;
            aOrbiterJ = ((aWandererB + RotL64(aPrevious, 3U)) + RotL64(aCarry, 19U)) + 0x4E85249A23861AE4ULL;
            aOrbiterG = ((aWandererA + RotL64(aIngress, 47U)) + RotL64(aCarry, 5U)) + 0x7AD3205EFADEF2D0ULL;
            aOrbiterE = ((aWandererC + RotL64(aCross, 57U)) + 0x7B5D9471E43C557BULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 12U)) & S_SALT1];
            aOrbiterI = ((aWandererG + RotL64(aIngress, 20U)) + 0x85AC446C6E2745D2ULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aCross, 13U)) + RotL64(aCarry, 47U)) + 0x818F17316A755303ULL;
            aOrbiterH = (aWandererJ + RotL64(aScatter, 35U)) + 0xC6423ABD85455D78ULL;
            //
