            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x9F4BA4F9898A37C3ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0x3EE42CA6BA7B214DULL;
            aOrbiterC = RotL64((aOrbiterC * 0x66638FC459734F1DULL), 5U);
