            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0xD10B75F631F91237ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x798D572947397C83ULL), 51U);
            //
