            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0x3E2F2B030C85C321ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x8C430CC3A869E777ULL;
