            //
            aOrbiterI = ((aOrbiterI + aOrbiterC) + 0x784A703839CE58E0ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x7048B333D9A72B0CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7B656E2B65D4D51BULL), 57U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x595841D7763D6631ULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 25U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x96268D4467E26332ULL;
