        //
        // Ingress:
        //      aFuseLaneC (-->), aFuseLaneA (-->), aShadowLaneD (-->), aKeyRowReadB (<-?->)
        //
        // Cross:
        //      aFuseLaneB (<--), aPoisonLaneA (<--), aPlasmaLaneC (<--), aShadowLaneA (<-?->)
        //
