            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 31106U)) & S_BLOCK1], 47U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 32050U)) & S_BLOCK1], 13U));
