            aScatter = (RotL64(aIngress, 3U) + RotL64(aCross, 50U)) ^ (RotL64(aCarry, 19U) + RotL64(aPrevious, 37U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = ((aWandererK + RotL64(aScatter, 51U)) + 0xF370E850EE0A9F91ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 4U)) & S_SALT1];
            aOrbiterC = (aWandererH + RotL64(aPrevious, 5U)) + 0x4D858FB28EAD5543ULL;
            aOrbiterJ = ((aWandererI + RotL64(aIngress, 29U)) + 0xA2B7BF77D1A424A5ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = ((aWandererA + RotL64(aCross, 57U)) + RotL64(aCarry, 53U)) + 0x03A9BD25F5926517ULL;
            aOrbiterH = ((aWandererE + RotL64(aScatter, 37U)) + RotL64(aCarry, 29U)) + 0x2CEB93CBD17CA987ULL;
            aOrbiterK = ((aWandererD + RotL64(aPrevious, 18U)) + RotL64(aCarry, 41U)) + 0x85C9493AFB9786E5ULL;
            aOrbiterD = (aWandererG + RotL64(aCross, 11U)) + 0x772836CE27EDB381ULL;
