            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x6D228C2E25610988ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x8ED604F63D317B62ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA1E2A3D29C518273ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x2BCA5BEC91282F7AULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x31C12A481D1E1D64ULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xB59A68F417C56C1DULL), 37U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x8E6ED14E1CD5A4FDULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x5AFC6B4A89F8B023ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x5F984B80E207E5CDULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x10B46DAB0E86EBB6ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x82ED2F0339CF8260ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 19U)) & S_SALT1];
