            aOrbiterC = (aOrbiterC + aOrbiterJ) + 0x3E3959F5246736D2ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterC) ^ 0x5076A7D8915DEBBAULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8A1B0C67F586A51BULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xA9AAB03A465E5B92ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0xAFE1EFD4A5B08382ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xF7F6E37ADB9E6CE7ULL), 5U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0x08675F4488607591ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x38849BB8B73808FCULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x08E3A8E844710CCDULL), 19U);
            //
            aIngress = RotL64(aOrbiterH, 51U) ^ aOrbiterK;
