            //
            aWandererK = aWandererK + ((((RotL64(aIngress, 27U) + RotL64(aOrbiterK, 13U)) + aOrbiterF) + RotL64(aCarry, 19U)) + aKeyRotateAWandererUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 60U) + RotL64(aOrbiterC, 51U)) + aOrbiterJ);
            aWandererI = aWandererI + (((RotL64(aScatter, 3U) + RotL64(aOrbiterF, 60U)) + aOrbiterD) + aKeyRotateAWandererUpdateSaltB[((aIndex + 8U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aCross, 11U) + RotL64(aOrbiterB, 3U)) + aOrbiterK);
            aWandererE = aWandererE + (((RotL64(aPrevious, 53U) + aOrbiterD) + RotL64(aOrbiterK, 29U)) + RotL64(aCarry, 53U));
            aWandererD = aWandererD ^ ((RotL64(aScatter, 21U) + aOrbiterC) + RotL64(aOrbiterF, 35U));
