            aOrbiterC = (((aWandererK + RotL64(aIngress, 20U)) + RotL64(aCarry, 5U)) + 0xAAC5B0A83DEA5EE0ULL) + aKeyRotateBOrbiterAssignSaltC[((aIndex + 26U)) & S_SALT1];
            aOrbiterG = (aWandererA + RotL64(aScatter, 5U)) + 0x139FB77C8586D769ULL;
            aOrbiterE = (aWandererH + RotL64(aCross, 51U)) + 0xD34F949AAC378ADEULL;
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 37U)) + RotL64(aCarry, 23U)) + 0xD6872E9885F853AEULL;
            aOrbiterK = (((aWandererB + RotL64(aCross, 43U)) + RotL64(aCarry, 51U)) + 0x26F557886C2FEA2EULL) + aKeyRotateBOrbiterAssignSaltD[(((31U - aIndex) + 18U)) & S_SALT1];
