            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0x3CD1F6DBEE0D913EULL) ^ aKeyRotateBOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
